function validate([items, capacity]) {
  if (!Array.isArray(items) || items.length < 1 || items.length > 100000) return 'items needs 1 to 10^5 entries.';
  for (const item of items) {
    if (!Array.isArray(item) || item.length !== 2) return 'Each item is a pair [price, weight].';
    if (item.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each price and weight is an integer between 1 and 10^4.';
  }
  if (!Number.isInteger(capacity) || capacity < 1 || capacity > 1000000000) return 'capacity is an integer between 1 and 10^9.';
  return null;
}

