function maxPrice(items, capacity) {
  const sorted = items.slice();
  sorted.sort((a, b) => b[0] * a[1] - a[0] * b[1]);

  let remaining = capacity;
  let total = 0;

  for (const [price, weight] of sorted) {
    if (weight >= remaining) {
      total += (price * remaining) / weight;
      return total;
    }
    total += price;
    remaining -= weight;
  }

  return -1;
}

