function maxPrice(items, capacity) {
  let available = 0;
  for (const item of items) available += item[1];
  if (available < capacity) return -1;
  const left = items.map(item => item[1]);
  let sum = 0;
  for (let unit = 0; unit < capacity; unit++) {
    let pick = -1;
    for (let i = 0; i < items.length; i++) {
      if (left[i] === 0) continue;
      if (pick === -1 || items[i][0] / items[i][1] > items[pick][0] / items[pick][1]) pick = i;
    }
    left[pick]--;
    sum += items[pick][0] / items[pick][1];
  }
  return sum;
}

