function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 6);
  const priceCap = large ? 10000 : [5, 20][Math.floor(rand() * 2)];
  const weightCap = large ? 10000 : [3, 10][Math.floor(rand() * 2)];
  const items = Array.from({ length: n }, () => [1 + Math.floor(rand() * priceCap), 1 + Math.floor(rand() * weightCap)]);
  let total = 0;
  for (const item of items) total += item[1];
  const mode = rand();
  let capacity;
  if (mode < 0.15) capacity = total + 1 + Math.floor(rand() * (large ? 1000000 : 5));
  else if (mode < 0.25) capacity = total;
  else capacity = 1 + Math.floor(rand() * total);
  return [items, capacity];
}
